import ctypes, json, os, secrets
from pathlib import Path
from ctypes import wintypes

class SecretError(Exception): pass

def store_path():
    home = Path(os.environ.get("LOCALAPPDATA", str(Path.home())))
    return Path(os.environ.get("CURATOR_SECRET_FILE", str(home/"Neur0StoreCurator"/"credentials.dpapi")))

class BLOB(ctypes.Structure):
    _fields_ = [("cbData", wintypes.DWORD), ("pbData", ctypes.POINTER(ctypes.c_ubyte))]

def _transform(raw, protect):
    if os.name != "nt":
        raise SecretError("DPAPI_requires_Windows")
    kernel = ctypes.windll.kernel32
    crypt = ctypes.windll.crypt32
    data = (ctypes.c_ubyte * len(raw)).from_buffer_copy(raw)
    src = BLOB(len(raw), data)
    dst = BLOB()
    flags = 0x01 # CRYPTPROTECT_UI_FORBIDDEN
    if protect:
        fn = crypt.CryptProtectData
        ok = fn(ctypes.byref(src), "Neur0StoreCurator", None, None, None, flags, ctypes.byref(dst))
    else:
        fn = crypt.CryptUnprotectData
        ok = fn(ctypes.byref(src), None, None, None, None, flags, ctypes.byref(dst))
    if not ok:
        raise SecretError("DPAPI_encrypt_failed" if protect else "DPAPI_decrypt_failed")
    try:
        return ctypes.string_at(dst.pbData, dst.cbData)
    finally:
        kernel.LocalFree(ctypes.cast(dst.pbData, ctypes.c_void_p))

def write(values, target=None):
    dest=Path(target or store_path())
    dest.parent.mkdir(parents=True, exist_ok=True)
    if dest.exists():
        raise SecretError("store_exists_refuse_overwrite")
    data = json.dumps(values, ensure_ascii=False, separators=(",",":")).encode("utf-8")
    ciphertext = _transform(data, True)
    tmp = dest.with_name(dest.name + "." + secrets.token_hex(6) + ".tmp")
    try:
        with tmp.open("xb") as f:
            f.write(ciphertext)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, dest)
    finally:
        if tmp.exists(): tmp.unlink()
    return dest

def read(target=None):
    dest=Path(target or store_path())
    if not dest.is_file():
        raise SecretError("store_missing")
    raw=dest.read_bytes()
    try:
        values=json.loads(_transform(raw,False).decode("utf-8"))
    except (ValueError,UnicodeError) as e:
        raise SecretError("DPAPI_invalid_store") from None
    if not isinstance(values,dict):
        raise SecretError("DPAPI_invalid_store")
    return values
