import json, os, re, sqlite3, sys, time, urllib.request, urllib.parse, urllib.error
from pathlib import Path

class Blocked(Exception): pass

def local_secrets():
    """Read only current user's locally encrypted DPAPI file; never log contents."""
    try:
        from secrets_store import read, store_path, SecretError
    except ImportError:
        return {}
    target=store_path()
    if not target.exists():return {}
    try:
        return read(target)
    except SecretError:
        raise Blocked("secure_credential_store_unavailable") from None

def config():
    saved=local_secrets()
    keys=("CURATOR_TELEGRAM_BOT_TOKEN","CURATOR_TELEGRAM_CHAT_ID",
        "CURATOR_TELEGRAM_USER_ID","CURATOR_MANAGED_CHAT_ID",
        "CURATOR_CHAT_URL","CURATOR_REPOSITORY","CURATOR_BRANCH",
        "CURATOR_EXPECTED_HEAD")
    c={}
    for k in keys:
        v=str(os.environ.get(k) or saved.get(k) or "").strip()
        if not v:raise Blocked("missing_config:"+k)
        c[k]=v
    try:
        c["chatid"]=int(c["CURATOR_TELEGRAM_CHAT_ID"])
        c["userid"]=int(c["CURATOR_TELEGRAM_USER_ID"])
    except ValueError: raise Blocked("invalid_telegram_identity")
    c["base"]=str(os.environ.get("CURATOR_BRIDGE_URL") or saved.get("CURATOR_BRIDGE_URL") or "http://127.0.0.1:17448").rstrip("/")
    b=urllib.parse.urlsplit(c["base"])
    u=urllib.parse.urlsplit(c["CURATOR_CHAT_URL"])
    if b.scheme!="http" or b.hostname not in ("127.0.0.1","localhost"):
        raise Blocked("bridge_must_use_loopback")
    if u.scheme!="https" or u.hostname!="chatgpt.com" or not re.search(r"/c/[0-9a-f-]{20,}$",u.path):
        raise Blocked("curator_must_be_existing_exact_chat")
    if not re.fullmatch(r"[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+",c["CURATOR_REPOSITORY"]):
        raise Blocked("invalid_repository")
    if not re.fullmatch("[0-9a-fA-F]{7,64}",c["CURATOR_EXPECTED_HEAD"]):
        raise Blocked("invalid_expected_head")
    default_db=str(Path(os.environ.get("LOCALAPPDATA",str(Path.home()))) / "Neur0StoreCurator" / "inbox.sqlite3")
    c["db"]=os.environ.get("CURATOR_INBOX_DB",default_db)
    return c

def call(url, body=None, timeout=8):
    data=None if body is None else json.dumps(body,ensure_ascii=False).encode("utf8")
    req=urllib.request.Request(url,data=data,headers={"Content-Type":"application/json"} if data else {})
    try:
        with urllib.request.urlopen(req,timeout=timeout) as r:
            obj=json.loads(r.read(1000000).decode("utf8"))
        if not isinstance(obj,dict): raise Blocked("invalid_json")
        return obj
    except urllib.error.HTTPError as e:
        # Never echo a URL containing the Telegram token.
        raise Blocked("http_"+str(e.code)) from None
    except (OSError,urllib.error.URLError,ValueError) as e:
        raise Blocked("network_"+type(e).__name__) from None

def bot(c,method,body):
    answer=call("https://api.telegram.org/bot"+c["CURATOR_TELEGRAM_BOT_TOKEN"]+"/"+method,body,19)
    if not answer.get("ok"): raise Blocked("telegram_api_failed")
    return answer

def notify(c,text,reply_id=0):
    p={"chat_id":c["chatid"],"text":text[:3800]}
    if reply_id:p["reply_parameters"]={"message_id":reply_id,"allow_sending_without_reply":True}
    return bot(c,"sendMessage",p)

def open_db(c):
    f=Path(c["db"]);f.parent.mkdir(parents=True,exist_ok=True)
    d=sqlite3.connect(str(f),timeout=8)
    d.row_factory=sqlite3.Row
    d.execute("PRAGMA journal_mode=WAL")
    d.executescript("""
    CREATE TABLE IF NOT EXISTS inbox(
      update_id INTEGER PRIMARY KEY, message_id INTEGER NOT NULL,
      body TEXT NOT NULL, state TEXT NOT NULL, assignment TEXT NOT NULL DEFAULT '',
      noted TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '');
    CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY,v TEXT NOT NULL);
    """)
    d.commit()
    return d

def offset(db):
    row=db.execute("SELECT v FROM meta WHERE k='offset'").fetchone()
    return int(row["v"]) if row else 0

def persist(db,update_id,message_id,text=None):
    with db:
        if text is not None:
            db.execute("INSERT OR IGNORE INTO inbox(update_id,message_id,body,state) VALUES(?,?,?,'RECEIVED')",
                       (update_id,message_id,text))
        db.execute("INSERT INTO meta(k,v) VALUES('offset',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",
                   (str(max(update_id+1,offset(db))),))

def mark(db,update_id,state,assignment="",error=""):
    with db:
        db.execute("UPDATE inbox SET state=?,assignment=CASE WHEN ?!='' THEN ? ELSE assignment END,error=? WHERE update_id=?",
                   (state,assignment,assignment,error[:140],update_id))

def note(db,update_id,state):
    with db:
        row=db.execute("SELECT noted FROM inbox WHERE update_id=?",(update_id,)).fetchone()
        if row is None or row["noted"]==state:return False
        db.execute("UPDATE inbox SET noted=? WHERE update_id=?",(state,update_id))
        return True

def exact_curator(c):
    r=call(c["base"]+"/api/supervisor-watchdog/managed-chats",timeout=6)
    rows=[a for a in r.get("chats",[]) if a.get("id")==c["CURATOR_MANAGED_CHAT_ID"]]
    if len(rows)!=1:raise Blocked("curator_not_registered")
    a=rows[0]
    for field,key in (("url","CURATOR_CHAT_URL"),("repository","CURATOR_REPOSITORY"),("branch","CURATOR_BRANCH")):
        if a.get(field)!=c[key]:raise Blocked("curator_"+field+"_mismatch")
    if a.get("enabled") is False:raise Blocked("curator_disabled")
    return a

def key(uid):return "telegram-curator-"+str(uid)

def find_assignment(c,uid):
    rows=call(c["base"]+"/api/supervisor-watchdog/agent-assignments",timeout=8).get("assignments",[])
    found=[a for a in rows if a.get("idempotencyKey")==key(uid)]
    if len(found)>1:raise Blocked("assignment_key_conflict")
    return found[0] if found else None

def send_once(c,uid,text):
    payload={
      "text":"[TG_CURATOR_TASK update_id="+str(uid)+"]\n"
        "Задача от авторизованного владельца. Проверяй фактические доказательства, "
        "не дублируй UNKNOWN, используй существующие чаты и логируй действия в foto6/boss. "
        "Никаких удалений и live-публикаций без отдельного одобрения.\nЗадание:\n"+text,
      "repository":c["CURATOR_REPOSITORY"],"branch":c["CURATOR_BRANCH"],
      "expectedHead":c["CURATOR_EXPECTED_HEAD"],"idempotencyKey":key(uid),
      "supervisorVerificationRequired":True,"priority":750}
    path="/api/supervisor-watchdog/managed-chats/"+urllib.parse.quote(c["CURATOR_MANAGED_CHAT_ID"],safe="")+"/assignments"
    return call(c["base"]+path,payload,12)

def deliver(db,c):
    rows=db.execute("SELECT * FROM inbox WHERE state IN ('RECEIVED','SENDING_UNKNOWN','QUEUED') ORDER BY update_id LIMIT 20").fetchall()
    for row in rows:
        uid=row["update_id"];state=row["state"]
        try:
            if state=="RECEIVED":
                # Preflight comes BEFORE the durable send intent.
                exact_curator(c)
                mark(db,uid,"SENDING_UNKNOWN")
                try:
                    assignment=send_once(c,uid,row["body"])
                except Blocked:
                    # Do not send a second POST when outcome may be UNKNOWN.
                    continue
                aid=str(assignment.get("id") or "")
                if not aid:continue
                mark(db,uid,"QUEUED",aid)
            else:
                a=find_assignment(c,uid)
                if a is None:
                    if state=="SENDING_UNKNOWN":mark(db,uid,"NEEDS_RECONCILIATION",error="assignment_not_found")
                    continue
                aid=str(a.get("id") or "")
                if row["assignment"] and row["assignment"]!=aid:
                    mark(db,uid,"NEEDS_RECONCILIATION",error="assignment_id_conflict");continue
                if state=="SENDING_UNKNOWN":mark(db,uid,"QUEUED",aid)
                submitted=a.get("dispatchSubmitAttempted") is True and int(a.get("dispatchCount") or 0)>0
                if submitted and a.get("state") in ("awaiting_evidence","completed"):
                    mark(db,uid,"SENT_CONFIRMED",aid)
                    if note(db,uid,"SENT_CONFIRMED"):
                        try:notify(c,"Задача #"+str(uid)+" доставлена куратору. Исполнение ещё проверяется.",row["message_id"])
                        except Blocked:pass
                elif a.get("state") in ("failed","blocked","cancelled"):
                    mark(db,uid,"BLOCKED",aid,error="bridge_"+str(a.get("state")))
                    if note(db,uid,"BLOCKED"):
                        try:notify(c,"Задача #"+str(uid)+" заблокирована Bridge; повторной отправки не будет.",row["message_id"])
                        except Blocked:pass
        except Blocked:
            # If no send intent was stored, safe to check again; otherwise reconcile only.
            continue

def receive(db,c,update):
    uid=update.get("update_id")
    if not isinstance(uid,int):return
    m=update.get("message") or {};chat=m.get("chat") or {};user=m.get("from") or {}
    allowed=chat.get("id")==c["chatid"] and user.get("id")==c["userid"]
    mid=int(m.get("message_id") or 0)
    text=m.get("text")
    if not allowed:
        persist(db,uid,mid);return
    if not isinstance(text,str):
        persist(db,uid,mid);return
    text=text.strip()
    if text in ("/status","/queue"):
        persist(db,uid,mid)
        rows=db.execute("SELECT update_id,state FROM inbox ORDER BY update_id DESC LIMIT 6").fetchall()
        lines=["#"+str(r["update_id"])+": "+r["state"] for r in rows]
        try:notify(c,"Очередь:\n"+("\n".join(lines) or "пуста"),mid)
        except Blocked:pass
        return
    if text in ("/help","/start"):
        persist(db,uid,mid)
        try:notify(c,"Пришли /task <задача> либо текст; /status — состояние очереди.",mid)
        except Blocked:pass
        return
    if text.startswith("/task"):text=text[5:].strip()
    elif text.startswith("/"):
        persist(db,uid,mid);return
    if not 1<=len(text)<=8000:
        persist(db,uid,mid);return
    persist(db,uid,mid,text)
    try:notify(c,"Задача #"+str(uid)+" принята в очередь, доставку проверю отдельно.",mid)
    except Blocked:pass

def main():
    c=config();exact_curator(c)
    if "--check" in sys.argv:
        print("CONFIG_OK exact_curator_binding_ok; no Telegram requests or sends");return
